import json, glob, os, re
def firstpass(s):
    """The model's answer before the notice (the first assistant JSON with final_answer)."""
    for m in s['messages']:
        if m.get('role')!='assistant': continue
        c=m.get('content')
        if isinstance(c,list): c=''.join(str(x.get('text','')) if isinstance(x,dict) else str(x) for x in c)
        if not c: continue
        mm=re.findall(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"', c)
        if mm:
            try: return json.loads('"'+mm[-1]+'"')
            except Exception: return mm[-1]
