"""Replay recorded first passes through the wording check, offline."""
import json, glob, os, re, sys, importlib.util

RUNS = {
 '9f49dd72':'baseline', 'bca9cc83':'d7b155f', 'e2c96b80':'3340e63',
 '8b90b9c5':'7628d2a', '3c5c61e1':'e5d4cc5', '37a3ebb7':'d8f5ef0',
 'cd1bd0d4':'3bb9672', 'b000c8ef':'5402cb1',
}

def load_module(commit):
    """answer_conventions.py as of one commit, exported to /tmp/offline/<commit>/."""
    d = f'/tmp/offline/{commit}'
    if not os.path.isdir(d):
        os.makedirs(d, exist_ok=True)
        for name in ('answer_conventions.py',):
            src = os.popen(f'git -C /workspace/harness show {commit}:solver/{name}').read()
            open(f'{d}/{name}','w').write(src)
    spec = importlib.util.spec_from_file_location(f'ac_{commit}', f'{d}/answer_conventions.py')
    mod = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = mod
    spec.loader.exec_module(mod)
    return mod

def text_of(m):
    c = m.get('content')
    if isinstance(c, list):
        return ''.join(str(x.get('text','')) if isinstance(x, dict) else str(x) for x in c)
    return c or ''

def first_pass(s):
    for m in s['messages']:
        if m.get('role') != 'assistant': continue
        c = text_of(m)
        if not c: continue
        mm = re.findall(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"', c)
        if mm:
            try: return json.loads('"'+mm[-1]+'"')
            except Exception: return mm[-1]
    return None

def seen_text(s):
    return "\n".join(text_of(m) for m in s['messages'] if m.get('role') == 'tool')

def noticed(s):
    return any(m.get('role')=='user' and 'checked against the training memory' in text_of(m) for m in s['messages'])

def charges(text):
    text = (text or '').strip()
    m = re.search(r'\[罪名\](.*?)(?:<eoa>|$)', text)
    if m: text = m.group(1).strip()
    text = re.sub(r'<eoa>.*', '', text).strip()
    for sep in [';','；',',','，','、']:
        if sep in text: return frozenset(p.strip() for p in text.split(sep) if p.strip())
    return frozenset([text]) if text else frozenset()

def samples(run, task):
    base = f'/workspace/runs/{run}/{task}/conversations'
    out = []
    for d in sorted(os.listdir(base)):
        if d == 'prepare': continue
        for f in sorted(glob.glob(f'{base}/{d}/sample-*.json')):
            s = json.load(open(f))
            if s['status'] != 'ok': continue
            out.append((d, os.path.basename(f), s))
    return out

def profile(run, task):
    mem = json.load(open(f'/workspace/runs/{run}/{task}/memory.json'))
    return mem.get('answer_profile') or {}

def collect():
    """Every recorded first pass with what the check did to it."""
    rows = []
    for run, label in RUNS.items():
        for task in ('LawBench','Symptom2Disease','USPTO'):
            try: prof = profile(run, task)
            except FileNotFoundError: continue
            for d, f, s in samples(run, task):
                fp = first_pass(s)
                if fp is None: continue
                rows.append(dict(run=run, label=label, task=task, index=d, sample=f,
                                 first=fp, final=s['prediction'], target=s['target'],
                                 fired=noticed(s), was_correct=s['was_correct'],
                                 seen=seen_text(s), profile=prof))
    return rows

if __name__ == '__main__':
    rows = collect()
    print('recorded first passes:', len(rows))
    from collections import Counter
    print(Counter(r['task'] for r in rows))
    # validate replay against recorded firing
    for commit, label in [('37a3ebb7','d8f5ef0'), ('cd1bd0d4','3bb9672'), ('b000c8ef','5402cb1')]:
        mod = load_module(commit)
        agree = Counter()
        for r in rows:
            if r['run'] != commit: continue
            pred = bool(mod.answer_notice(r['profile'], r['first'], r['seen']))
            agree[(pred, r['fired'])] += 1
        print(label, dict(agree))
